// Web Flow's pure sandbox presentation model. It never authorizes or runs Tasks.
(function(global){
  'use strict';
  const fields=['taskId','version','manifestHash','contentHash'];
  const bounded=(x,n=120)=>String(x==null?'':x).slice(0,n);
  const taskKey=task=>fields.map(k=>task[k]).join('|');
  const pinsEqual=(a,b)=>fields.every(k=>a&&b&&a[k]===b[k]);
  const terminal=new Set(['completed','failed','stopped','interrupted','cancelled','canceled','unknown']);
  const taskStates={E_TASK_NOT_INSTALLED:'missing',E_TASK_REMOVED:'removed',
    E_TASK_DISABLED:'disabled',E_TASK_INITIALIZATION:'initialization',
    E_BUILTIN_VERSION_UNAVAILABLE:'runtime'};
  const errorState=error=>taskStates[error?.code]|| (error&&error.code==='E_REVISION'?'changed':
    error&&['E_PERMISSION','E_TOOL_DISABLED','E_OWNER'].includes(error.code)?'unavailable':'error');
  // Installation state comes from the Task Authority, never from display seeds.
  function taskReadMessage(error){
    if(!error)return '未读取到有效的任务安装。请到“我的”安装或恢复此任务，再刷新脚本状态。';
    if(error.code==='E_PERMISSION')return error.message==='Task is disabled or not installed'?
      '此任务尚未安装或已停用。请到“我的”安装或恢复此任务，再刷新脚本状态。':
      '任务或网站授权不可用。请到“我的”核对任务与网站授权，再刷新脚本状态。';
    return ({
      E_TASK_NOT_INSTALLED:'此脚本尚未安装。打开安装审阅，确认固定任务后再刷新。',
      E_TASK_REMOVED:'你已卸载此脚本，不会自动装回。需要使用时可打开安装审阅重新安装。',
      E_TASK_DISABLED:'此脚本已停用。打开任务管理可恢复，刷新或升级不会自动启用。',
      E_TASK_INITIALIZATION:'内置脚本初始化失败。请重试初始化；仍失败时展开诊断或打开安装审阅。',
      E_BUILTIN_VERSION_UNAVAILABLE:'浏览器运行时已更新，此脚本的原验证已失效。请打开任务管理，对同一固定任务包重新验证并确认安装，再刷新脚本状态。',
      E_REVISION:'任务安装版本或验证状态已变化。请到“我的”核对固定版本与验证状态，再刷新脚本状态。',
      E_TOOL_DISABLED:'Web Flow 已停用。请到“扩展”恢复应用后重新打开。',
      E_OWNER:'当前应用无权读取此任务。请到“扩展”核对 Web Flow 的任务授权后重新打开。'
    })[error.code]||'任务状态读取失败。请刷新脚本状态；仍失败时展开详情查看诊断信息。';
  }
  function filterTasks(rows,query,filter,starred,sort='favorite'){
    const q=String(query||'').trim().toLocaleLowerCase();
    const saved=new Set(Array.isArray(starred)?starred:[]);
    return rows.filter(row=>{
      if(filter==='available'&&row.state!=='available')return false;
      if(filter==='attention'&&!['changed','unavailable','error',...Object.values(taskStates)].includes(row.state))return false;
      if(filter==='favorite'&&!saved.has(taskKey(row)))return false;
      return !q||[row.title,row.taskId,row.site,row.version].some(s=>
        String(s||'').toLocaleLowerCase().includes(q));
    }).sort((a,b)=>(sort==='name'?0:
      Number(saved.has(taskKey(b)))-Number(saved.has(taskKey(a))))||
      a.title.localeCompare(b.title,'zh-CN'));
  }
  function businessState(snapshot){
    const v=snapshot&&snapshot.value;
    if(!v||typeof v!=='object')return 'unverified';
    if(v.status==='success'&&Array.isArray(v.results)&&v.results.length)return 'reported-success';
    if(['blocked','no_results','dom_changed','dom_unavailable','stopped'].includes(v.status))return v.status;
    return 'unverified';
  }
  function projectRun(s,task,now=Date.now()){
    const result=s&&s.result;
    const persisted=Boolean(s?.runId&&s?.resultId&&result&&result.tag==='controller-result'&&
      result.runId===s.runId&&result.resultId===s.resultId&&terminal.has(result.state)&&result.state!=='unknown');
    const runtimeOk=Boolean(persisted&&result.outcome&&result.outcome.ok===true);
    return {
      clientRequestId:bounded(s&&s.clientRequestId,80),taskId:task.taskId,version:task.version,
      runId:bounded(s&&s.runId,80),resultId:bounded(s&&s.resultId,80),
      state:bounded(s&&s.state||'unknown',36),
      retirementState:bounded(s&&s.retirementState||'unknown',40),
      resultPersisted:persisted,runtimeOk,
      notSubmittedFenced:s?.semantic==='NOT_SUBMITTED_FENCED'&&s.state==='cancelled'&&!s.runId&&!s.resultId,
      business:runtimeOk?businessState(s):'unverified',
      count:runtimeOk&&Number.isSafeInteger(s.value&&s.value.count)?Math.min(9999,Math.max(0,s.value.count)):null,
      at:Number.isFinite(now)?now:Date.now(),
      delivery:'not_observed',aiReply:'not_observed'
    };
  }
  function recentRecords(value){
    if(!Array.isArray(value))return [];
    return value.slice(0,12).filter(x=>x&&typeof x==='object'&&
      typeof x.taskId==='string'&&typeof x.clientRequestId==='string')
      .map(x=>({
        clientRequestId:bounded(x.clientRequestId,80),taskId:bounded(x.taskId,60),
        version:bounded(x.version,30),runId:bounded(x.runId,80),resultId:bounded(x.resultId,80),
        state:bounded(x.state,36),retirementState:bounded(x.retirementState,40),
        resultPersisted:x.resultPersisted===true,runtimeOk:x.runtimeOk===true,
        notSubmittedFenced:x.notSubmittedFenced===true&&x.state==='cancelled'&&!x.runId&&!x.resultId,
        business:bounded(x.business,40),count:Number.isSafeInteger(x.count)?x.count:null,
        at:Number.isFinite(x.at)?x.at:0,delivery:'not_observed',aiReply:'not_observed'
      }));
  }
  function pendingRecord(value){
    if(!value||typeof value!=='object'||
      typeof value.clientRequestId!=='string'||!/^[A-Za-z0-9._:-]{1,80}$/.test(value.clientRequestId)||
      typeof value.taskId!=='string'||typeof value.version!=='string')return null;
    const task=value.task;
    const locator={clientRequestId:value.clientRequestId,taskId:value.taskId,version:value.version,
      at:Number.isFinite(value.at)?value.at:0,state:'unknown'};
    if(task&&task.taskId===value.taskId&&fields.every(k=>typeof task[k]==='string')&&
      typeof task.installationId==='string'&&Number.isSafeInteger(task.generation))
      locator.task=Object.fromEntries([...fields,'installationId','generation'].map(k=>[k,task[k]]));
    if(typeof value.params?.query==='string'&&value.params.query.length<=120&&value.params.limit===3)
      locator.params={query:value.params.query,limit:3};
    return locator;
  }
  function released(s){
    // UNKNOWN and completed alone never establish retirement. A pre-submit
    // cancellation needs the original Authority's affirmative durable fence.
    if(!s||s.state==='unknown')return false;
    if(s.semantic==='NOT_SUBMITTED_FENCED'&&s.state==='cancelled'&&!s.runId&&!s.resultId)return true;
    return ['completed','failed','stopped','interrupted','cancelled','canceled'].includes(s.state)&&
      s.retirementState==='released'&&s.result?.tag==='controller-result'&&
      Boolean(s.runId)&&Boolean(s.resultId)&&terminal.has(s.result.state)&&s.result.state!=='unknown'&&
      s.result.runId===s.runId&&s.result.resultId===s.resultId;
  }
  const summary=(tasks,records)=>({
    reviewed:tasks.length,available:tasks.filter(x=>x.state==='available').length,
    attention:tasks.filter(x=>['changed','unavailable','error',...Object.values(taskStates)].includes(x.state)).length,
    latest:Array.isArray(records)?records[0]||null:null
  });
  global.OpenDeskWebFlowModel=Object.freeze({
    taskKey,pinsEqual,errorState,taskReadMessage,filterTasks,businessState,projectRun,recentRecords,summary,
    isTerminal:s=>terminal.has(s),pendingRecord,released,bounded
  });
})(globalThis);

// Web Flow Markdown inputs are untrusted data, never execution authority.
(function(global){
  'use strict';
  const HEADER='<!-- webflow-todo:v1 -->', NAMES=['输入','任务','产出','验收'];
  const RULES=['auto:sum-count-marker:v1','auto:doubled-marker:v1'];
  function bad(code,message,line){throw Object.assign(new Error(message+(line?'（第 '+line+' 行）':'')),{code,line:line||null});}
  function deepFreeze(x){if(x&&typeof x==='object'){Object.values(x).forEach(deepFreeze);Object.freeze(x);}return x;}
  const object=x=>x&&typeof x==='object'&&!Array.isArray(x)&&Object.getPrototypeOf(x)===Object.prototype;
  function parse(text){
    if(typeof text!=='string'||new TextEncoder().encode(text).length>65536)bad('E_MD_SIZE','MD 必须是不超过 64 KiB 的文本');
    const lines=text.replace(/^\uFEFF/u,'').replace(/\r\n?/gu,'\n').split('\n');
    const first=lines.findIndex(x=>x.trim());
    if(first<0||lines[first].trim()!==HEADER)bad('E_MD_FORMAT','首个非空行必须为 webflow-todo:v1 标记',first+1);
    let title='',goal='',area=null,field=null,fence=null,goalSeen=false;
    const tasks=[],ids=new Map();
    const put=(line,n)=>{
      if(area==='goal')goal+=line+'\n';
      else if(area&&field)area.fields[field]+=line+'\n';
      else if(line.trim())bad('E_MD_FORMAT','正文必须归属目标或任务字段',n);
    };
    for(let i=first+1;i<lines.length;i++){
      const line=lines[i],n=i+1,open=/^ {0,3}(\x60{3,}|~{3,})/u.exec(line);
      if(fence){
        if(open&&open[1][0]===fence.c&&open[1].length>=fence.n&&line.slice(open[0].length).trim()==='')fence=null;
        put(line,n);continue;
      }
      if(open){fence={c:open[1][0],n:open[1].length,line:n};put(line,n);continue;}
      const h=/^ {0,3}(#{1,3})[ \t]+(.+?)[ \t]*$/u.exec(line);
      if(!h){put(line,n);continue;}
      const level=h[1].length,heading=h[2].replace(/[ \t]+#+[ \t]*$/u,'').trim();
      if(level===1){
        if(title||area||!heading)bad('E_MD_FORMAT','一级标题必须唯一且在目标之前',n);
        title=heading;
      }else if(level===2){
        if(!title)bad('E_MD_FORMAT','先写队列名称',n);
        if(heading==='目标'){
          if(goalSeen||tasks.length)bad('E_MD_FORMAT','目标只能出现一次且在任务之前',n);
          goalSeen=true;area='goal';field=null;
        }else{
          const m=/^(T\d{2})[ \t]+(\S.*)$/u.exec(heading);
          if(!m)bad('E_MD_FORMAT','二级标题必须是目标或 T01 任务名称',n);
          if(!goal.trim())bad('E_MD_REQUIRED','任务前缺少目标内容',n);
          if(ids.has(m[1]))bad('E_MD_DUPLICATE',m[1]+' 重复，首次位于第 '+ids.get(m[1])+' 行',n);
          if(tasks.length>=16)bad('E_MD_LIMIT','任务数量超过 16',n);
          ids.set(m[1],n);area={id:m[1],title:m[2],line:n,fields:{}};tasks.push(area);field=null;
        }
      }else{
        if(!area||area==='goal'||!NAMES.includes(heading))bad('E_MD_FORMAT','只允许输入、任务、产出、验收四个字段',n);
        if(Object.hasOwn(area.fields,heading))bad('E_MD_DUPLICATE',area.id+' 重复字段 '+heading,n);
        area.fields[heading]='';field=heading;
      }
    }
    if(fence)bad('E_MD_FORMAT','代码围栏没有关闭',fence.line);
    if(!title||!goal.trim()||!tasks.length)bad('E_MD_REQUIRED','缺少标题、目标或任务');
    for(const t of tasks){
      for(const key of NAMES){
        if(!t.fields[key]?.trim())bad('E_MD_REQUIRED',t.id+' 缺少字段 '+key,t.line);
        t.fields[key]=t.fields[key].trim();
      }
      t.acceptance=t.fields['验收'];
      if(!RULES.includes(t.acceptance)&&!/^manual:[^\n]{3,200}$/u.test(t.acceptance))
        bad('E_MD_ACCEPTANCE',t.id+' 验收必须是已实现的 auto 规则或明确的 manual: 项',t.line);
    }
    return deepFreeze({format:'webflow-todo:v1',title,goal:goal.trim(),tasks});
  }
  function githubRaw(source){
    if(typeof source!=='string'||source.length>1500||/%(?:2e|2f|5c)|\\|[\u0000-\u001f]/iu.test(source))
      bad('E_MD_SOURCE','不接受该 GitHub 链接');
    let url;try{url=new URL(source);}catch{bad('E_MD_SOURCE','无效的 GitHub 链接');}
    if(url.protocol!=='https:'||url.username||url.password||url.search||url.hash)bad('E_MD_SOURCE','只允许纯 HTTPS 文件链接');
    let a=url.pathname.split('/').slice(1);
    if(url.hostname==='github.com'){
      if(a.length<5||a[2]!=='blob')bad('E_MD_SOURCE','GitHub 链接必须指向 blob 文件');
      a=[a[0],a[1],a[3],...a.slice(4)];
    }else if(url.hostname!=='raw.githubusercontent.com')bad('E_MD_SOURCE','只允许 GitHub 公开源文件');
    if(a.length<4||a.some(x=>!x||x==='.'||x==='..'||!/^[a-z0-9._-]+$/iu.test(x))||!a.at(-1).endsWith('.md'))
      bad('E_MD_SOURCE','MD 路径或版本无效');
    return 'https://raw.githubusercontent.com/'+a.join('/');
  }
  async function sha(text,digest){
    const doDigest=digest||global.crypto?.subtle?.digest?.bind(global.crypto.subtle,'SHA-256');
    if(typeof doDigest!=='function')bad('E_MD_DIGEST','SHA-256 不可用，不能固定版本');
    const bytes=new TextEncoder().encode(text),result=await doDigest(bytes);
    const b=Object.prototype.toString.call(result)==='[object ArrayBuffer]'?new Uint8Array(result):
      ArrayBuffer.isView(result)?new Uint8Array(result.buffer,result.byteOffset,result.byteLength):null;
    if(!b||b.length!==32)bad('E_MD_DIGEST','摘要回执错误');
    return Array.from(b,x=>x.toString(16).padStart(2,'0')).join('');
  }
  async function readGithub(source,{fetcher,digest}={}){
    const url=githubRaw(source);
    if(typeof fetcher!=='function')bad('E_MD_FETCH','缺少已授权的网络读取接口；隔离页面禁止直接 fetch');
    let r;try{r=await fetcher(url);}
    catch(error){
      if(['E_NETWORK_NOT_SUBMITTED','E_CHROME_PERMISSION_REQUIRED','E_PERMISSION'].includes(error?.code))
        bad('E_MD_PERMISSION','网络权限未确认，请使用原宿主授权入口');
      if(error?.code==='E_HTTP'&&/HTTP (?:401|403)\b/u.test(error.message||''))
        bad('E_MD_AUTH','仓库可能是私有文件，需使用已有授权读取通道');
      if(error?.code==='E_HTTP'&&/HTTP 404\b/u.test(error.message||''))
        bad('E_MD_FETCH','GitHub 返回 HTTP 404：文件不存在或当前无权访问');
      if(error?.code==='E_LIMIT')bad('E_MD_SIZE','GitHub 文件超出宿主网络读取预算');
      bad('E_MD_FETCH','经授权的 GitHub 读取失败（'+String(error?.code||'E_NETWORK')+'）；不使用内嵌样例');
    }
    if(r?.status===401||r?.status===403)bad('E_MD_AUTH','私有仓库需要单独授权通道');
    if(!r?.ok||typeof r.text!=='function')bad('E_MD_FETCH','文件读取失败 HTTP '+(r?.status??'?')+'，可能不存在或无权访问');
    const content=await r.text();
    if(typeof content!=='string')bad('E_MD_FETCH','HTTP 结果不是文本');
    const workflow=parse(content),version=await sha(content,digest);
    return deepFreeze({source,url,content,version,workflow});
  }
  function spec(w){
    if(!object(w)||w.tasks?.length!==2||w.tasks[0]?.id!=='T01'||w.tasks[1]?.id!=='T02'||
       w.tasks[0].acceptance!==RULES[0]||w.tasks[1].acceptance!==RULES[1])
      bad('E_DEMO_SCHEMA','演示只接受求和 T01 → 翻倍 T02');
    const a=/^numbers:\s*\[([0-9,\s]+)\]$/u.exec(w.tasks[0].fields['输入']);
    const b=/^artifact:\s*T01\s*\nmultiplier:\s*([1-9]\d*)$/u.exec(w.tasks[1].fields['输入']);
    if(!a||!b)bad('E_DEMO_SCHEMA','T02 必须只接收 T01 成果引用和倍数');
    const tokens=a[1].split(',').map(x=>x.trim());
    if(tokens.length<1||tokens.length>20||tokens.some(x=>!/^(0|[1-9]\d*)$/u.test(x)))
      bad('E_DEMO_SCHEMA','数字数组格式不正确');
    const numbers=tokens.map(Number),multiplier=Number(b[1]),sum=numbers.reduce((x,y)=>x+y,0);
    if(!Number.isSafeInteger(multiplier)||multiplier>100||numbers.some(x=>!Number.isSafeInteger(x))||
      !Number.isSafeInteger(sum*multiplier))bad('E_DEMO_SCHEMA','输入超过安全计算范围');
    return deepFreeze({numbers,multiplier});
  }
  function context(w,c){
    spec(w);
    if(typeof c?.marker!=='string'||!/^[a-z0-9-]{16,80}$/iu.test(c.marker)||
      !/^[a-f0-9]{64}$/u.test(c.version||''))bad('E_DEMO_CONTEXT','缺少本轮随机标记或冻结版本');
  }
  function marker(){
    if(typeof global.crypto?.randomUUID!=='function')bad('E_DEMO_CONTEXT','需要安全随机标记');
    return global.crypto.randomUUID();
  }
  const fields=(a,keys)=>object(a)&&Object.keys(a).length===keys.length&&keys.every(x=>Object.hasOwn(a,x));
  const equal=(a,b)=>{
    if(a===b)return true;
    if(Array.isArray(a)||Array.isArray(b))return Array.isArray(a)&&Array.isArray(b)&&a.length===b.length&&a.every((x,i)=>equal(x,b[i]));
    return object(a)&&object(b)&&Object.keys(a).length===Object.keys(b).length&&
      Object.keys(a).every(k=>Object.hasOwn(b,k)&&equal(a[k],b[k]));
  };
  function verifyT01(w,c,a){
    context(w,c);const values=spec(w).numbers;
    if(!fields(a,['sum','count','marker','inputVersion'])||!Number.isSafeInteger(a.sum)||
       a.sum!==values.reduce((x,y)=>x+y,0)||a.count!==values.length||
       a.marker!==c.marker||a.inputVersion!==c.version)
      bad('E_DEMO_ACCEPTANCE','T01 成果未通过独立验收');
    return true;
  }
  function readback(w,c,saved,read){
    verifyT01(w,c,saved);
    if(!equal(saved,read))bad('E_DEMO_READBACK','T01 保存与独立读回不一致');
    verifyT01(w,c,read);return read;
  }
  function verifyT02(w,c,saved,read,a){
    const upstream=readback(w,c,saved,read);
    if(!fields(a,['doubled','marker','inputVersion'])||!Number.isSafeInteger(a.doubled)||
       a.doubled!==upstream.sum*spec(w).multiplier||a.marker!==c.marker||a.inputVersion!==c.version)
       bad('E_DEMO_ACCEPTANCE','T02 成果未通过独立验收');
    return true;
  }
  function promptT01(w,c){
    context(w,c);
    return '总目标：'+w.goal+'\n任务 T01：'+w.tasks[0].fields['任务']+
      '\n输入：'+JSON.stringify(spec(w).numbers)+'\n随机交接标记：'+c.marker+'\n输入版本：'+c.version+
      '\n只输出 JSON {sum,count,marker,inputVersion}。不要声明已保存、已验收。';
  }
  function promptT02(w,c,saved,read){
    const prior=readback(w,c,saved,read);
    return '总目标：'+w.goal+'\n任务 T02：'+w.tasks[1].fields['任务']+
      '\n已保存并独立读回的 T01 成果内容：'+JSON.stringify(prior)+
      '\n倍数：'+spec(w).multiplier+
      '\n只输出 JSON {doubled,marker,inputVersion}。不要声明已保存、已验收。';
  }
  global.OpenDeskMdWorkflow=Object.freeze({parse,githubRaw,sha,readGithub,spec,context,marker,
    verifyT01,readback,verifyT02,promptT01,promptT02});
})(globalThis);
